import json, csv
from collections import defaultdict
from pathlib import Path

base = Path('/app')
with open(base/'submissions/solution.json') as f:
    sol = json.load(f)
with open(base/'data/config.json') as f:
    config = json.load(f)

def read_csv(name):
    with open(base/'data'/name, newline='') as f:
        return list(csv.DictReader(f))

stations = {r['station_id']: r for r in read_csv('stations.csv')}
segments_rows = read_csv('segments.csv')
segments = {}
seg_by_pair = {}
for r in segments_rows:
    key = (r['from_station'], r['to_station'])
    segments[key] = r
    seg_by_pair[frozenset(key)] = r
trains = {r['train_id']: r for r in read_csv('trains.csv')}
rolling = {r['rolling_stock_id']: r for r in read_csv('rolling_stock.csv')}
crews = {r['crew_id']: r for r in read_csv('crews.csv')}
connections = read_csv('passenger_connections.csv')
throats = {(r['station_id'], r['side']): r for r in read_csv('station_throats.csv')}
disruptions = defaultdict(list)
for r in read_csv('disruption_windows.csv'):
    disruptions[r['segment_id']].append((float(r['start_minute']), float(r['end_minute']), r['reason']))

station_order = {sid:int(r['order_index']) for sid,r in stations.items()}
station_gap = {sid:float(r['min_platform_gap_minutes']) for sid,r in stations.items()}
station_plats = {sid:int(r['platform_count']) for sid,r in stations.items()}
train_rows = sol['trains']
violations = []
coverage = []

# schema / key coverage
seen = set()
extra = []
for i,tr in enumerate(train_rows):
    tid = tr.get('train_id')
    if tid in seen:
        violations.append(('schema/key','train_id='+str(tid),'Each train should appear once','duplicate row','exactly 1'))
    seen.add(tid)
    if tid not in trains:
        extra.append(tid)
missing = sorted(set(trains)-seen)
if missing:
    for tid in missing:
        violations.append(('schema/key',f'train_id={tid}','Every public train requires one exported row','missing','present'))
for tid in extra:
    violations.append(('schema/key',f'train_id={tid}','No extra train rows outside public timetable','present','must be absent'))
coverage.append(('schema/nullability and key coverage','covered',f\"rows={len(train_rows)}, missing={len(missing)}, extra={len(extra)}\"))

# domain, path, time, segment use, platform presence, throat uses, stock/crew collection
segment_uses = []
platform_occ = defaultdict(list)
throat_uses = defaultdict(list)
stock_assign = defaultdict(list)
crew_assign = defaultdict(list)
actual_train_times = {}
status_domain = {'run','short_turn','cancel'}

for tr in train_rows:
    tid = tr.get('train_id')
    spec = trains.get(tid)
    key = f'train_id={tid}'
    # required top-level keys
    for fld in ['train_id','status','rolling_stock_id','crew_id','events']:
        if fld not in tr:
            violations.append(('schema/nullability',key,f'Missing required field {fld}','missing','present'))
    status = tr.get('status')
    if status not in status_domain:
        violations.append(('identifier domains',key,'status must be one of run/short_turn/cancel',status,'{run,short_turn,cancel}'))
    rs = tr.get('rolling_stock_id')
    cr = tr.get('crew_id')
    if rs not in rolling:
        violations.append(('identifier domains',key,'rolling_stock_id must exist in rolling_stock.csv',rs,'public rolling_stock_id'))
    if cr not in crews:
        violations.append(('identifier domains',key,'crew_id must exist in crews.csv',cr,'public crew_id'))
    if spec is None:
        continue
    events = tr.get('events')
    if not isinstance(events,list):
        violations.append(('schema/nullability',key,'events must be a list',type(events).__name__,'list'))
        continue
    direction = spec['direction']
    o = spec['origin']; d = spec['destination']
    oi = station_order[o]; di = station_order[d]
    step = 1 if direction=='east' else -1
    path_ids = [sid for sid,idx in sorted(station_order.items(), key=lambda kv: kv[1]) if (oi <= idx <= di if step==1 else di <= idx <= oi)]
    if direction=='west':
        path_ids = list(reversed(path_ids))
    if status == 'cancel':
        if events:
            violations.append(('schema/nullability',key,'Cancelled train must have empty events list',len(events),'0'))
        continue
    if not events:
        violations.append(('schema/nullability',key,'Running or short-turned train must have events',0,'>0'))
        continue
    # event schema and domains
    for j,ev in enumerate(events):
        ekey = f'{tid}.events[{j}]'
        for fld in ['station_id','arrival','departure','platform']:
            if fld not in ev:
                violations.append(('schema/nullability',ekey,f'Missing required field {fld}','missing','present'))
        sid = ev.get('station_id')
        if sid not in stations:
            violations.append(('identifier domains',ekey,'station_id must exist in stations.csv',sid,'public station_id'))
            continue
        plat = ev.get('platform')
        if not isinstance(plat,int):
            violations.append(('identifier domains',ekey,'platform must be an integer',repr(plat),'integer'))
        else:
            if plat < 1 or plat > station_plats[sid]:
                violations.append(('identifier domains',ekey,f'Platform must be in 1..{station_plats[sid]} at {sid}',plat,f'1..{station_plats[sid]}'))
        for fld in ['arrival','departure']:
            val = ev.get(fld)
            if not isinstance(val,(int,float)):
                violations.append(('schema/nullability',ekey,f'{fld} must be numeric',repr(val),'number'))
            else:
                if val < 0 or val > float(config['planning_horizon_minutes']):
                    violations.append(('identifier domains',ekey,f'{fld} must lie within planning horizon',val,f'0..{config[\"planning_horizon_minutes\"]}'))
    # path/order
    event_stations = [ev['station_id'] for ev in events if ev.get('station_id') in stations]
    if status == 'run':
        if event_stations "'!= path_ids:
            violations.append(('"'time/location',key,'Run train must visit full corridor path in order',event_stations,path_ids))
    elif status == 'short_turn':
        if spec['allow_short_turn'] "'!= '"'1':
            violations.append(('frozen/nonanticipative and disposition',key,'Train not authorized to short turn',status,'run or cancel only'))
        if event_stations and event_stations[0] "'!= o:
            violations.append(('"'time/location',key,'Short-turn train must start at origin',event_stations[0],o))
        if event_stations:
            final = event_stations[-1]
            if final == d:
                violations.append(('time/location',key,'Short-turn train must end before original destination',final,'turnback station before destination'))
            if stations[final]['can_turnback'] "'!= '"'1':
                violations.append(('time/location',key,'Short-turn train final station must be turnback-capable',final,'can_turnback=1'))
            prefix = path_ids[:len(event_stations)]
            if event_stations "'!= prefix:
                violations.append(('"'time/location',key,'Short-turn events must follow corridor prefix in order',event_stations,prefix))
    # event times & resources
    dep0 = events[0]['departure']; arr_last = events[-1]['arrival']
    actual_train_times[tid] = (dep0, arr_last)
    if dep0 < float(spec['planned_departure']):
        violations.append(('time/location',key,'Departure cannot precede planned departure',dep0,f'>={spec[\"planned_departure\"]}'))
    # dwell and nondecreasing
    for j,ev in enumerate(events):
