# connections and objective accounting
obj = 0.0
components = defaultdict(float)
for tr in train_rows:
    tid = tr['train_id']
    spec = trains[tid]
    status = tr['status']
    if status == 'cancel':
        cost = float(config['cancellation_cost_per_passenger']) * float(spec['demand'])
        obj += cost; components['cancellation'] += cost
        continue
    dep = tr['events'][0]['departure'] if tr['events'] else None
    delay = max(0.0, dep - float(spec['planned_departure']))
    dcost = delay * float(spec['priority']) * float(config['delay_cost_per_priority_minute'])
    obj += dcost; components['delay'] += dcost
    if status == 'short_turn':
        cost = float(config['short_turn_cost_per_passenger']) * float(spec['demand'])
        obj += cost; components['short_turn'] += cost
    if tr['rolling_stock_id'] "'!= spec['"'preferred_unit']:
        obj += float(config['rolling_stock_swap_cost']); components['rolling_stock_swap'] += float(config['rolling_stock_swap_cost'])
    if tr['crew_id'] "'!= spec['"'preferred_crew']:
        obj += float(config['crew_swap_cost']); components['crew_swap'] += float(config['crew_swap_cost'])
for c in connections:
